export type SafetyMode = "balanced" | "strict";
export type PublishedRewritePolicy = "deny" | "confirm";

export interface SafetyLayer {
  readonly mode?: SafetyMode;
  readonly protectedBranches?: readonly string[];
  readonly publishedRewrite?: PublishedRewritePolicy;
}

export interface SafetyLayers {
  readonly global?: SafetyLayer;
  readonly workspace?: SafetyLayer;
  readonly folder?: SafetyLayer;
}

export interface EffectiveSafetySettings {
  readonly mode: SafetyMode;
  readonly protectedBranches: readonly string[];
  readonly publishedRewrite: PublishedRewritePolicy;
}

const minimumProtectedBranches: readonly string[] = [
  'main',
  'master',
  'release/*',
];

/**
 * Combines values inspected from Extension Host Global, Workspace, and Folder.
 * Safety values are monotonic: lower layers can only add protections.
 */
export function mergeSafetyLayers(layers: SafetyLayers): EffectiveSafetySettings {
  let mode: SafetyMode = SETTING_DEFAULTS['gitWorkbench.safety.mode'];
  let publishedRewrite: PublishedRewritePolicy = SETTING_DEFAULTS['gitWorkbench.safety.publishedRewrite'];
  const protectedBranches: string[] = [...minimumProtectedBranches];

  for (const layer of [layers.global, layers.workspace, layers.folder]) {
    if (!layer) continue;
    if (layer.mode === 'strict') { mode = 'strict'; publishedRewrite = 'deny'; }
    if (layer.publishedRewrite === 'deny') publishedRewrite = 'deny';
    if (!Array.isArray(layer.protectedBranches)) continue;
    for (const branch of layer.protectedBranches) {
      if (typeof branch !== 'string') continue;
      const normalizedBranch = branch.trim();
      if (normalizedBranch && !protectedBranches.includes(normalizedBranch)) protectedBranches.push(normalizedBranch);
    }
  }

  return { mode, protectedBranches, publishedRewrite };
}


